if __name__ == "__main__":
    robot = None
    try:
        # main 里再赋给全局 robot；这里只起个占位便于 finally 兜底
        main()
    except KeyboardInterrupt:
        print("interrupted")
    except Exception as e:
        print(f"error: {e}")
    finally:
        # 没法可靠拿到 main 内的 robot（main 内部已 destroy 也无副作用）
        print("released")

    # ponytail: max_speed 0.3 让挥手节奏自然；想慢改 0.1
    try:
        move(robot, ["left_arm"], position_seq, is_blocking=True, max_speed=0.3, timeout_s=10)
    finally:
        try:
            robot.request_shutdown()
            robot.wait_for_shutdown()
            robot.destroy()
        except Exception:
            pass


if __name__ == "__main__":
    main()
